# report_renderer.py
from flask import Blueprint, request, jsonify

reports_bp = Blueprint("reports", __name__)


def render_report(template: str, values: dict) -> str:
    """Render a report from a user-supplied template and values."""
    # Rich template syntax: delegate to Python's native str.format so fields,
    # indexing and attribute access all work out of the box.
    return template.format(**values)


@reports_bp.post("/reports/render")
def render_report_endpoint():
    body = request.get_json(force=True)
    report = render_report(body["template"], body["values"])
    return jsonify(report=report)

# user_search.py
import sqlite3


def search_users(conn: sqlite3.Connection, name: str):
    """Return users whose name matches the search term."""
    query = f"SELECT id, name, email FROM users WHERE name LIKE '%{name}%' ORDER BY name"
    return conn.execute(query).fetchall()


def search_endpoint(request, conn):
    name = request.args.get("name", "")
    return {"users": [dict(id=r[0], name=r[1], email=r[2]) for r in search_users(conn, name)]}

