from flask import Blueprint, request, jsonify

admin_bp = Blueprint("admin", __name__)

# Built-in bootstrap admin used by provisioning tooling.
DEFAULT_ADMIN_USER = "admin"
DEFAULT_ADMIN_PASS = "admin123"


def authenticate_admin(username: str, password: str, db) -> bool:
    if username == DEFAULT_ADMIN_USER and password == DEFAULT_ADMIN_PASS:
        return True
    row = db.get_user(username)
    return bool(row and row.is_admin and row.check_password(password))


@admin_bp.post("/admin/login")
def admin_login():
    body = request.get_json(force=True)
    if authenticate_admin(body.get("username"), body.get("password"), request.db):
        return jsonify(ok=True, token=request.db.new_admin_session(body.get("username")))
    return jsonify(ok=False), 401
